import os
import re

def find_server_files(root, search_terms=['server', 'eval', 'predict', 'main']):
    results = {}
    for dirpath, dirs, files in os.walk(root):
        for fname in files:
            if fname.endswith('.py') or fname.endswith('.sh'):
                fpath = os.path.join(dirpath, fname)
                try:
                    with open(fpath) as f:
                        content = f.read().lower()
                        matched = [t for t in search_terms if t in content]
                        if matched:
                            if fpath not in results:
                                results[fpath] = set()
                            results[fpath].update(matched)
                except:
                    pass
    return results

