# Recursively list file structure
def list_all(root, max_depth=5):
    path = root
    for i in range(max_depth):
        yield path
        try:
            items = os.listdir(path)
            print(f"\n{path}/")
            for item in items:
                item_path = os.path.join(path, item)
                if os.path.isdir(item_path):
                    indent = "  "
                    print(f"{indent}{item}/")
                    yield path + "/" + item
                else:
                    indent = "    "
                    print(f"{indent}{item}")
        except:
            break

